// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        bool okReference;
        bool retReference;
        try c.transfer(contract_address, tos, vs) returns (bool result) {
            okReference = true;
            retReference = result;
        } catch {
            okReference = false;
        }

        assertTrue(!okReference || retReference);
    }

}
